// newHandler returns an http.Handler that serves the root endpoint.
// It is exported for use in tests.
func newHandler() http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		w.Write([]byte("OK"))
	})
}

func main() {
	// Open (or create) the SQLite database file.
	db, err := sql.Open("sqlite3", "linkshelf.db")
	if err != nil {
		log.Fatalf("failed to open database: %v", err)
	}
	// Ensure the DB is closed on program exit.
	defer db.Close()

	// Initialise the schema (creates the `links` table if it does not exist).
	if err := store.InitSchema(db); err != nil {
		log.Fatalf("failed to initialise schema: %v", err)
	}

	// Wire the DB to the store package (store.DB is used by the handlers).
	store.DB = db

	// Set up HTTP routing.
	mux := http.NewServeMux()

	// Register API routes.
	registerAPIHandlers(mux)

	// Serve static UI files from the ./web directory.
	mux.HandleFunc("/", staticHandler)

	// Start the HTTP server on port 8080.
	addr := ":8080"
	log.Printf("server listening on %s", addr)
	if err := http.ListenAndServe(addr, mux); err != nil {
		log.Fatalf("server error: %v", err)
	}
}

// registerAPIHandlers registers the JSON API routes on the provided mux.
func registerAPIHandlers(mux *http.ServeMux) {
	// Handle /api/links for GET (list) and POST (create).
	mux.HandleFunc("/api/links", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			links, err := store.List()
			if err != nil {
				http.Error(w, `{"error":"failed to list links"}`, http.StatusInternalServerError)
				return
			}
			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(links)
		case http.MethodPost:
			var payload struct {
				Title string `json:"title"`
				URL   string `json:"url"`
			}
			if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
				http.Error(w, `{"error":"invalid json"}`, http.StatusBadRequest)
				return
			}
			if payload.Title == "" || payload.URL == "" {
				http.Error(w, `{"error":"title and url required"}`, http.StatusBadRequest)
				return
			}
			id, err := store.Create(payload.Title, payload.URL)
			if err != nil {
				http.Error(w, `{"error":"`+err.Error()+`"}`, http.StatusBadRequest)
				return
			}
			link := store.Link{
				ID:    id,
				Title: payload.Title,
				URL:   payload.URL,
			}
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusCreated)
			json.NewEncoder(w).Encode(link)
		default:
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		}
	})
	// Handle /api/links/{id} for DELETE.
	mux.HandleFunc("/api/links/", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodDelete {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}
		parts := strings.Split(strings.Trim(r.URL.Path, "/"), "/")
		if len(parts) < 3 {
			http.NotFound(w, r)
			return
		}
		id, err := strconv.Atoi(parts[2])
		if err != nil {
			http.NotFound(w, r)
			return
		}
		if err := store.Delete(int64(id)); err != nil {
			http.Error(w, `{"error":"`+err.Error()+`"}`, http.StatusNotFound)
			return
		}
		w.WriteHeader(http.StatusNoContent)
	})
}

// staticHandler serves files from the ./web directory while protecting against
// path‑traversal attacks. Requests to the root path ("/") are mapped to
// "/index.html".
func staticHandler(w http.ResponseWriter, r *http.Request) {
	upath := r.URL.Path
	if upath == "/" {
		upath = "/index.html"
	}
	if strings.Contains(upath, "..") {
		http.Error(w, "invalid path", http.StatusBadRequest)
		return
	}
	fsPath := filepath.Join("web", filepath.FromSlash(upath))
	f, err := os.Open(fsPath)
	if err != nil {
		http.NotFound(w, r)
		return
	}
	defer f.Close()
	http.ServeContent(w, r, fsPath, getModTime(f), f)
}

// getModTime extracts the modification time of a file for http.ServeContent.
func getModTime(f *os.File) (modTime time.Time) {
	if info, err := f.Stat(); err == nil {
		modTime = info.ModTime()
	}
	return
}

